from p"benchmark_harness.jo" import clock, size_argument
step=(mode:bool x:int64):>int64=>(if mode x*1664525+1013904223 else x*1103515245+12345) and 2147483647
kernel=(count:int64):>int64=>{
let value:int64=1 let i:int64=0
loop i <? count {value=step(true value) i+=1}
return value
}
main=(args:array<string>):>int64=>{
let count=size_argument(args 100000000)
let started=clock() let result=kernel(count) let finished=clock()
printl"{result} {finished-started}" return 0
}
